import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { contractsAPI } from '../services/api';
import { Sidebar } from './DashboardPage';
import toast from 'react-hot-toast';

function Field({ label, value }) {
  const empty = !value || value === 'Non mentionné';
  return (
    <div style={{ marginBottom: 14 }}>
      <div style={{ fontSize: 11, fontWeight: 600, color: '#F59E0B', textTransform: 'uppercase', letterSpacing: '0.5px', marginBottom: 4 }}>{label}</div>
      <div style={{ fontSize: 14, color: empty ? '#4B5563' : '#fff', fontStyle: empty ? 'italic' : 'normal' }}>{value || 'Non mentionné'}</div>
    </div>
  );
}

function Section({ title, icon, children }) {
  return (
    <div className="card" style={{ marginBottom: 16 }}>
      <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 16, fontWeight: 700, marginBottom: 20, display: 'flex', alignItems: 'center', gap: 8, color: '#F59E0B' }}>
        <span>{icon}</span> {title}
      </h3>
      {children}
    </div>
  );
}

function TwoCol({ children }) {
  return <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 24px' }}>{children}</div>;
}

export default function ContractDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [contract, setContract] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    contractsAPI.get(id)
      .then(res => setContract(res.data))
      .catch(() => { toast.error('Contrat introuvable'); navigate('/dashboard'); })
      .finally(() => setLoading(false));
  }, [id]);

  const handleDownloadPDF = () => {
    const token = localStorage.getItem('access_token');
    fetch(`http://localhost:8000/api/contracts/${id}/export-pdf/`, {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(res => {
        if (!res.ok) throw new Error();
        return res.blob();
      })
      .then(blob => {
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `resume_${contract?.file_name?.replace(/\.[^.]+$/, '') || 'contrat'}.pdf`;
        a.click();
        window.URL.revokeObjectURL(url);
      })
      .catch(() => toast.error('Erreur lors du téléchargement'));
  };

  if (loading) return (
    <div style={{ display: 'flex', minHeight: '100vh', background: 'var(--dark)' }}>
      <Sidebar active="contracts" />
      <main style={{ marginLeft: 260, flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ width: 40, height: 40, border: '3px solid #F59E0B', borderTopColor: 'transparent', borderRadius: '50%', animation: 'spin 1s linear infinite', margin: '0 auto 16px' }} />
          <p style={{ color: '#F59E0B' }}>Chargement...</p>
        </div>
      </main>
    </div>
  );

  const s = contract?.summary || {};
  const pg = s.presentation_generale || {};
  const cp = s.clauses_principales || {};
  const parties = pg.parties_prenantes || {};
  const perimetre = pg.perimetre || {};
  const admin = cp.informations_administratives || {};
  const finances = cp.conditions_financieres || {};
  const obligations = cp.obligations_parties || {};
  const suivi = cp.suivi_reception || {};
  const clauses = cp.clauses_particulieres || {};

  return (
    <div style={{ display: 'flex', minHeight: '100vh', background: 'var(--dark)' }}>
      <Sidebar active="contracts" />
      <main style={{ marginLeft: 260, flex: 1, padding: '40px 36px' }}>
        <div className="animate-fade-in" style={{ maxWidth: 900 }}>
          <div style={{ marginBottom: 28 }}>
            <button onClick={() => navigate('/dashboard')} style={{ background: 'none', color: '#6B7280', fontSize: 14, cursor: 'pointer', marginBottom: 12 }}>
              ← Retour au dashboard
            </button>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 12 }}>
              <div>
                <h1 style={{ fontFamily: 'var(--font-display)', fontSize: 28, fontWeight: 800, marginBottom: 4 }}>{contract?.file_name}</h1>
                <p style={{ color: '#6B7280', fontSize: 14 }}>Résumé IA — 32 points clés extraits</p>
              </div>
              <button onClick={handleDownloadPDF} style={{
                display: 'flex', alignItems: 'center', gap: 8,
                background: '#F59E0B', color: '#0D0D1A',
                border: 'none', borderRadius: 8, padding: '10px 20px',
                fontWeight: 700, fontSize: 15, cursor: 'pointer',
                fontFamily: 'var(--font-condensed)',
              }}>
                📥 Télécharger le résumé PDF
              </button>
            </div>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 24, padding: '14px 20px', background: 'rgba(16,185,129,0.1)', border: '1px solid rgba(16,185,129,0.2)', borderRadius: 10 }}>
            <span style={{ fontSize: 20 }}>✅</span>
            <span style={{ color: '#10B981', fontWeight: 600 }}>Résumé généré avec succès</span>
          </div>

          <Section title="1 — Présentation générale et contexte" icon="📋">
            <Field label="Objet du contrat" value={pg.objet_contrat} />
            <Field label="Contexte et objectifs" value={pg.contexte_objectifs} />
            <TwoCol>
              <Field label="Maître d'ouvrage" value={parties.maitre_ouvrage} />
              <Field label="Maître d'œuvre" value={parties.maitre_oeuvre} />
              <Field label="Entreprise / Groupement" value={parties.entrepreneur} />
              <Field label="Sous-traitants" value={parties.sous_traitants} />
              <Field label="Lot(s)" value={perimetre.lots} />
              <Field label="Localisation" value={perimetre.localisation} />
              <Field label="Type de travaux" value={perimetre.type_travaux} />
              <Field label="Délai d'exécution" value={perimetre.delai_execution} />
              <Field label="Date de démarrage" value={perimetre.date_demarrage} />
              <Field label="Ordre de service" value={perimetre.ordre_de_service} />
            </TwoCol>
          </Section>

          <Section title="2a — Informations administratives" icon="🏛️">
            <TwoCol>
              <Field label="Numéro / Référence" value={admin.numero_marche} />
              <Field label="N° Approbation DNCMP" value={admin.numero_approbation} />
              <Field label="Type de marché" value={admin.type_marche} />
              <Field label="Mode de passation" value={admin.mode_passation} />
              <Field label="Date de notification" value={admin.date_notification} />
              <Field label="Source de financement" value={admin.source_financement} />
              <Field label="Tribunal compétent" value={admin.tribunal_competent} />
            </TwoCol>
          </Section>

          <Section title="2b — Conditions financières" icon="💰">
            <TwoCol>
              <Field label="Montant HT" value={finances.montant_ht} />
              <Field label="Montant TTC" value={finances.montant_ttc} />
              <Field label="Taux TVA" value={finances.taux_tva} />
              <Field label="Conditions de paiement" value={finances.conditions_paiement} />
              <Field label="Révision des prix" value={finances.revision_prix} />
              <Field label="Caution bonne exécution" value={finances.caution_bonne_execution} />
              <Field label="Retenue de garantie" value={finances.retenue_garantie} />
            </TwoCol>
          </Section>

          <Section title="2c — Obligations des parties" icon="📝">
            <Field label="Obligations du Maître d'ouvrage" value={obligations.obligations_maitre_ouvrage} />
            <Field label="Obligations du Maître d'œuvre" value={obligations.obligations_maitre_oeuvre} />
            <Field label="Obligations de l'Entreprise" value={obligations.obligations_entrepreneur} />
          </Section>

          <Section title="2d — Suivi et réception" icon="🔍">
            <TwoCol>
              <Field label="Supervision" value={suivi.supervision} />
              <Field label="Réception provisoire" value={suivi.reception_provisoire} />
              <Field label="Réception définitive" value={suivi.reception_definitive} />
            </TwoCol>
          </Section>

          <Section title="2e — Clauses particulières" icon="⚖️">
            <Field label="Pénalités de retard" value={clauses.penalites_retard} />
            <Field label="Conditions de résiliation" value={clauses.conditions_resiliation} />
            <Field label="Règlement des litiges" value={clauses.reglement_litiges} />
          </Section>
        </div>
      </main>
    </div>
  );
}
